// @vitest-environment happy-dom
import { createElement as h } from 'react';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import MemoMarquee, { Marquee } from './Marquee.js';
import { MarqueeCurtain } from './MarqueeCurtain.js';
import { DEFAULT_WORLD_CLOCK_CITIES, WorldClocks } from './WorldClocks.js';
import type { Event, EventPost } from '../events.js';

const post = (relevance: number): EventPost => ({ relevance }) as EventPost;
const event = (uuid: string, created: string, relevances: number[], extra: Record<string, unknown> = {}): Event =>
  ({ id: 1, uuid, title: `Title ${uuid}`, summary: 's', status: 'open', created_at: created, updated_at: created, posts_count: relevances.length, posts: relevances.map(post), ...extra }) as Event;

beforeEach(() => vi.useFakeTimers());
afterEach(() => {
  cleanup();
  vi.useRealTimers();
  vi.restoreAllMocks();
});

describe('Marquee', () => {
  const strong = [8, 8, 8, 8];
  const track = (container: HTMLElement) => container.firstElementChild!.firstElementChild as HTMLElement;

  it('renders nothing when no event passes the thresholds', () => {
    const { container } = render(h(Marquee, { events: [event('weak', '2026-03-11T00:00:00Z', [1, 1, 1, 1])] }));
    expect(container.innerHTML).toBe('');
  });

  it('applies the post count, average and median thresholds independently', () => {
    const events = [
      event('few-posts', '2026-03-11T00:00:00Z', [9, 9, 9]),
      event('low-average', '2026-03-11T00:00:00Z', [1, 1, 1, 1]),
      // median 8 but average 4.8
      event('low-average-high-median', '2026-03-11T00:00:00Z', [0, 0, 8, 8, 8]),
      // average 7 (>= 5) but median 5 (< 7)
      event('low-median', '2026-03-11T00:00:00Z', [5, 5, 5, 20]),
      event('ok', '2026-03-11T00:00:00Z', strong),
    ];
    render(h(Marquee, { events }));
    expect(screen.queryByText('Title few-posts')).toBeNull();
    expect(screen.queryByText('Title low-average')).toBeNull();
    expect(screen.queryByText('Title low-average-high-median')).toBeNull();
    expect(screen.queryByText('Title low-median')).toBeNull();
    expect(screen.getByText('Title ok')).toBeTruthy();
  });

  it('uses the posts array length when posts_count is not a number and skips thresholds set to zero', () => {
    const noCount = event('no-count', '2026-03-11T00:00:00Z', strong, { posts_count: undefined });
    const empty = event('empty', '2026-03-11T00:00:00Z', []);
    render(h(Marquee, { events: [noCount, empty], minPostsCount: 0, minAverageRelevance: 0, minMedianRelevance: 0 }));
    expect(screen.getByText('Title no-count')).toBeTruthy();
    // zero thresholds also admit an event with no posts at all
    expect(screen.getByText('Title empty')).toBeTruthy();
  });

  it('rejects an event with no posts under the default thresholds', () => {
    const { container } = render(h(Marquee, { events: [event('empty', '2026-03-11T00:00:00Z', [])] }));
    expect(container.innerHTML).toBe('');
  });

  it('computes the median of an even number of posts as the mean of the middle pair', () => {
    // sorted 4,10,10,20 -> median 10 (>= 7); average 11 (>= 5)
    render(h(Marquee, { events: [event('even', '2026-03-11T00:00:00Z', [20, 10, 4, 10])] }));
    expect(screen.getByText('Title even')).toBeTruthy();
    cleanup();
    // sorted 1,1,2,20 -> median 1.5 (< 7) although the average of 6 passes
    const { container } = render(h(Marquee, { events: [event('even-low', '2026-03-11T00:00:00Z', [20, 1, 1, 2])] }));
    expect(container.innerHTML).toBe('');
  });

  it('lists events oldest first with the configured box styling', () => {
    const events = [event('late', '2026-03-11T12:00:00Z', strong), event('early', '2026-03-11T06:00:00Z', strong)];
    const { container } = render(h(Marquee, { events, heightPx: 90, backgroundColor: 'rgb(1, 2, 3)', borderColor: 'rgb(4, 5, 6)' }));
    const titles = Array.from(container.querySelectorAll('span')).map((span) => span.textContent);
    expect(titles).toEqual(['Title early', 'Title late']);
    const box = container.firstElementChild as HTMLElement;
    expect(box.style.height).toBe('90px');
    expect(box.style.backgroundColor).toBe('rgb(1, 2, 3)');
    expect(box.style.borderTop).toContain('rgb(4, 5, 6)');
  });

  it('sizes the animation from the content width after the layout delay and on resize', () => {
    let width = 1000;
    vi.spyOn(HTMLElement.prototype, 'scrollWidth', 'get').mockImplementation(() => width);
    const { container } = render(h(Marquee, { events: [event('a', '2026-03-11T00:00:00Z', strong)], pixelsPerSecond: 100, minDurationSeconds: 10 }));
    const trackEl = track(container);
    expect(trackEl.style.animation).toContain('marqueeFlow 20s');

    act(() => {
      vi.advanceTimersByTime(100);
    });
    // (1920 + 1000) / 100
    expect(trackEl.style.animation).toContain('marqueeFlow 29.2s');

    width = 80;
    act(() => {
      fireEvent(window, new Event('resize'));
    });
    // (1920 + 80) / 100 = 20
    expect(trackEl.style.animation).toContain('marqueeFlow 20s');

    // a content width of 80 gives 20s, below a 25 second floor
    cleanup();
    const floor = render(h(Marquee, { events: [event('a', '2026-03-11T00:00:00Z', strong)], pixelsPerSecond: 100, minDurationSeconds: 25 }));
    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(track(floor.container).style.animation).toContain('marqueeFlow 25s');
  });

  it('never divides by less than one pixel per second', () => {
    vi.spyOn(HTMLElement.prototype, 'scrollWidth', 'get').mockReturnValue(80);
    const { container } = render(h(Marquee, { events: [event('a', '2026-03-11T00:00:00Z', strong)], pixelsPerSecond: 0 }));
    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(track(container).style.animation).toContain('marqueeFlow 2000s');
  });

  it('ignores the layout timer when nothing is rendered and cleans up on unmount', () => {
    const removeListener = vi.spyOn(window, 'removeEventListener');
    const { container, unmount } = render(h(Marquee, { events: [] }));
    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(container.innerHTML).toBe('');
    unmount();
    expect(removeListener).toHaveBeenCalledWith('resize', expect.any(Function));
  });

  it('reports each completed animation cycle', () => {
    const onCycleComplete = vi.fn();
    const { container } = render(h(Marquee, { events: [event('a', '2026-03-11T00:00:00Z', strong)], onCycleComplete }));
    fireEvent.animationIteration(track(container));
    fireEvent.animationIteration(track(container));
    expect(onCycleComplete).toHaveBeenCalledTimes(2);
  });

  it('exports a memoised component that renders the same output', () => {
    render(h(MemoMarquee, { events: [event('memo', '2026-03-11T00:00:00Z', strong)] }));
    expect(screen.getByText('Title memo')).toBeTruthy();
  });
});

describe('MarqueeCurtain', () => {
  it('announces the brand and completes once after five seconds', () => {
    const onComplete = vi.fn();
    const { container } = render(h(MarqueeCurtain, { onComplete }));
    expect(container.textContent).toBe('This is fifthbell.');
    expect(container.querySelectorAll('svg')).toHaveLength(2);

    act(() => {
      vi.advanceTimersByTime(4999);
    });
    expect(onComplete).not.toHaveBeenCalled();
    act(() => {
      vi.advanceTimersByTime(1);
    });
    expect(onComplete).toHaveBeenCalledOnce();
  });

  it('does not complete after being unmounted', () => {
    const onComplete = vi.fn();
    const { unmount } = render(h(MarqueeCurtain, { onComplete }));
    unmount();
    act(() => {
      vi.advanceTimersByTime(10_000);
    });
    expect(onComplete).not.toHaveBeenCalled();
  });
});

describe('WorldClocks', () => {
  const fixed = new Date('2026-03-11T15:30:00Z');
  const cities = [
    { city: 'ROME', timezone: 'Europe/Rome' },
    { city: 'TOKYO', timezone: 'Asia/Tokyo' },
    { city: 'Springfield', timezone: 'America/Chicago' },
  ];

  const clockText = (container: HTMLElement) => Array.from(container.firstElementChild!.children).map((node) => node.textContent);

  it('shows the time in the first city with its translated label', () => {
    const { container } = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false, language: 'es' }));
    expect(clockText(container)).toEqual(['16:30', 'ROMA']);
    expect((container.firstElementChild as HTMLElement).style.width).toBe('200px');
  });

  it('rotates through the cities with a fade, keeps untranslated labels and wraps around', () => {
    const { container } = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false, language: 'en', rotateIntervalMs: 1000, transitionDurationMs: 100, widthPx: 120 }));
    const root = container.firstElementChild as HTMLElement;
    expect(root.style.width).toBe('120px');

    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(root.style.opacity).toBe('0');
    act(() => {
      vi.advanceTimersByTime(100);
    });
    expect(root.style.opacity).toBe('1');
    expect(clockText(container)).toEqual(['00:30', 'TOKYO']);

    act(() => {
      vi.advanceTimersByTime(1100);
    });
    expect(clockText(container)).toEqual(['10:30', 'Springfield']);

    act(() => {
      vi.advanceTimersByTime(1100);
    });
    expect(clockText(container)).toEqual(['16:30', 'ROME']);
  });

  it('reshuffles the pool when the rotation wraps around', () => {
    const random = vi.spyOn(Math, 'random').mockReturnValue(0);
    const pair = cities.slice(0, 2);
    const { container } = render(h(WorldClocks, { currentTime: fixed, cities: pair, shuffleCities: true, rotateIntervalMs: 1000, transitionDurationMs: 0 }));
    // random() == 0 swaps every element with the first: [ROME, TOKYO] -> [TOKYO, ROME]
    expect(clockText(container)[1]).toBe('TOKIO');
    const callsBefore = random.mock.calls.length;
    act(() => {
      vi.advanceTimersByTime(1002);
    });
    expect(clockText(container)[1]).toBe('ROMA');
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(random.mock.calls.length).toBeGreaterThan(callsBefore);
  });

  it('enforces a 500 ms floor on the rotation interval', () => {
    const { container } = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false, rotateIntervalMs: 10, transitionDurationMs: 0 }));
    act(() => {
      vi.advanceTimersByTime(499);
    });
    expect(clockText(container)[1]).toBe('ROMA');
    act(() => {
      vi.advanceTimersByTime(2);
    });
    expect(clockText(container)[1]).toBe('TOKIO');
  });

  it('falls back to the default city list when none is given', () => {
    const { container } = render(h(WorldClocks, { currentTime: fixed, shuffleCities: false, language: 'en' }));
    expect(clockText(container)[1]).toBe(DEFAULT_WORLD_CLOCK_CITIES[0].city);
    cleanup();
    const emptyList = render(h(WorldClocks, { currentTime: fixed, cities: [], shuffleCities: false, language: 'en' }));
    expect(clockText(emptyList.container)[1]).toBe(DEFAULT_WORLD_CLOCK_CITIES[0].city);
  });

  it('follows the wall clock every second when no time is supplied', () => {
    vi.setSystemTime(new Date('2026-03-11T15:30:00Z'));
    const { container } = render(h(WorldClocks, { cities, shuffleCities: false }));
    expect(clockText(container)[0]).toBe('16:30');
    act(() => {
      vi.setSystemTime(new Date('2026-03-11T15:31:00Z'));
      vi.advanceTimersByTime(1000);
    });
    expect(clockText(container)[0]).toBe('16:31');
  });

  it('adopts a new supplied time', () => {
    const view = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false }));
    view.rerender(h(WorldClocks, { currentTime: new Date('2026-03-11T18:45:00Z'), cities, shuffleCities: false }));
    expect(clockText(view.container)[0]).toBe('19:45');
  });

  it('shows the broadcast override clock when valid and the real zone time otherwise', () => {
    const override = { startTime: '09:15', startedAt: '2026-03-11T15:00:00Z' };
    const withOverride = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false, timeOverride: override }));
    // 30 minutes after a 09:15 start
    expect(clockText(withOverride.container)[0]).toBe('09:45');
    cleanup();
    const invalid = render(h(WorldClocks, { currentTime: fixed, cities, shuffleCities: false, timeOverride: { startTime: 'nope', startedAt: override.startedAt } }));
    expect(clockText(invalid.container)[0]).toBe('16:30');
  });

  it('stops its timers on unmount', () => {
    const clear = vi.spyOn(globalThis, 'clearInterval');
    const { unmount } = render(h(WorldClocks, { cities, shuffleCities: false, rotateIntervalMs: 1000 }));
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    unmount();
    expect(clear).toHaveBeenCalled();
    expect(vi.getTimerCount()).toBe(0);
  });
});

// @vitest-environment happy-dom
import { createElement as h, createRef } from 'react';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { ArticleSlide } from './ArticleSlide.js';
import { CallsignSlide } from './CallsignSlide.js';
import { LiveEventSlide } from './LiveEventSlide.js';
import { slideStyles } from './slideStyles.js';
import type { LiveEventData } from '../../segments/fetchLiveEvents.js';

const { getColor } = vi.hoisted(() => ({ getColor: vi.fn() }));
vi.mock('fast-average-color', () => ({
  FastAverageColor: class {
    getColor = getColor;
  },
}));

const originalTimeZone = process.env.TZ;

beforeEach(() => {
  process.env.TZ = 'UTC';
  getColor.mockReset();
  vi.useFakeTimers();
});
afterEach(() => {
  cleanup();
  vi.useRealTimers();
  vi.restoreAllMocks();
  if (originalTimeZone === undefined) delete process.env.TZ;
  else process.env.TZ = originalTimeZone;
});

const decodeQr = (src: string) => decodeURIComponent(src.replace('data:image/svg+xml;charset=utf-8,', ''));

describe('slideStyles', () => {
  it('declares the keyframes and classes the slides rely on', () => {
    for (const name of ['kenburns', 'slideTransition', 'scaleIn', 'fadeIn', 'slideUpFade', 'marqueeFlow']) {
      expect(slideStyles).toContain(`@keyframes ${name}`);
    }
    for (const cls of ['animate-slide-transition', 'animate-scale-in', 'animate-fade-in', 'animate-fade-in-delay', 'animate-slide-up']) {
      expect(slideStyles).toContain(`.${cls}`);
    }
  });
});

describe('ArticleSlide', () => {
  const item = { id: '7', headline: 'Big headline', summary: 'Short summary', imageUrl: 'https://img.test/a.jpg', category: 'Science', url: 'https://modoitaliano.fm/a' };

  it('shows the headline, summary, category, progress and a QR code for the article', () => {
    const { container } = render(h(ArticleSlide, { newsItem: item, progress: 42 }));
    expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Big headline');
    expect(screen.getByText('Short summary')).toBeTruthy();
    expect(screen.getByText('Science')).toBeTruthy();
    expect(container.innerHTML).toContain('width: 42%');

    const photo = screen.getByAltText('Big headline') as HTMLImageElement;
    expect(photo.getAttribute('src')).toBe(item.imageUrl);
    const qr = screen.getByAltText('Article QR code') as HTMLImageElement;
    expect(qr.src.startsWith('data:image/svg+xml;charset=utf-8,')).toBe(true);
    const svg = decodeQr(qr.getAttribute('src')!);
    expect(svg).toContain('<svg');
    expect(svg).toContain('fill="transparent"');
    expect(svg).toContain('fill="white"');
  });

  it('encodes a different QR code for a different article url', () => {
    const first = render(h(ArticleSlide, { newsItem: item, progress: 0 }));
    const firstQr = (screen.getByAltText('Article QR code') as HTMLImageElement).getAttribute('src');
    first.unmount();
    render(h(ArticleSlide, { newsItem: { ...item, url: 'https://modoitaliano.fm/other' }, progress: 0 }));
    expect((screen.getByAltText('Article QR code') as HTMLImageElement).getAttribute('src')).not.toBe(firstQr);
  });

  it('omits the category chip and falls back to a placeholder image when the item has none', () => {
    const { container } = render(h(ArticleSlide, { newsItem: { ...item, category: undefined, imageUrl: '' }, progress: 0 }));
    expect(screen.queryByText('Science')).toBeNull();
    for (const img of Array.from(container.querySelectorAll('img')).slice(0, 2)) {
      expect(img.getAttribute('src')).toBe('https://picsum.photos/seed/fallback/1920/1080');
    }
  });

  it('tints the slide with the dominant colour of the loaded image', () => {
    getColor.mockReturnValue({ hex: '#123456' });
    const { container } = render(h(ArticleSlide, { newsItem: item, progress: 0 }));
    const overlay = container.querySelector('.mix-blend-multiply') as HTMLElement;
    expect(overlay.style.background).toContain('#b21100');
    fireEvent.load(container.querySelector('img') as HTMLImageElement);
    expect(getColor).toHaveBeenCalledOnce();
    expect(overlay.style.background).toContain('#123456');
  });

  it('keeps the default tint and logs when the colour cannot be read', () => {
    const error = vi.spyOn(console, 'error').mockImplementation(() => {});
    getColor.mockImplementation(() => {
      throw new Error('tainted canvas');
    });
    const { container } = render(h(ArticleSlide, { newsItem: item, progress: 0 }));
    fireEvent.load(container.querySelector('img') as HTMLImageElement);
    expect(error).toHaveBeenCalledWith('Error getting average color', expect.any(Error));
    expect((container.querySelector('.mix-blend-multiply') as HTMLElement).style.background).toContain('#b21100');
  });
});

describe('CallsignSlide', () => {
  const start = new Date('2026-03-11T15:30:45Z');
  const props = { currentTime: start, audioRef: createRef<HTMLAudioElement>() };
  const timeNode = (container: HTMLElement) => container.querySelector('.animate-fade-in-delay') as HTMLElement;

  it('introduces the brand mark first and reveals the New York time and tagline after the intro', () => {
    const { container } = render(h(CallsignSlide, props));
    expect(timeNode(container).style.opacity).toBe('0');
    expect(timeNode(container).textContent).toBe('11:30:45');
    expect(container.textContent).toContain('This is fifthbell.');

    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(timeNode(container).style.opacity).toBe('0');
    act(() => {
      vi.advanceTimersByTime(500);
    });
    expect(timeNode(container).style.opacity).toBe('1');
  });

  it('fades the large bell out and the corner bell in after two seconds', () => {
    const { container } = render(h(CallsignSlide, props));
    const large = container.querySelector('.animate-scale-in') as HTMLElement;
    const corner = container.querySelector('.top-4') as HTMLElement;
    expect([large.style.opacity, corner.style.opacity]).toEqual(['1', '0']);
    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect([large.style.opacity, corner.style.opacity]).toEqual(['0', '1']);
  });

  it('advances the clock every second from the real time', () => {
    vi.setSystemTime(start);
    const { container } = render(h(CallsignSlide, props));
    act(() => {
      vi.advanceTimersByTime(1000);
    });
    expect(timeNode(container).textContent).toBe('11:30:46');
    act(() => {
      vi.advanceTimersByTime(2000);
    });
    expect(timeNode(container).textContent).toBe('11:30:48');
  });

  it('adopts a new starting time and stops ticking when unmounted', () => {
    const view = render(h(CallsignSlide, props));
    view.rerender(h(CallsignSlide, { ...props, currentTime: new Date('2026-03-11T20:00:00Z') }));
    expect(timeNode(view.container).textContent).toBe('16:00:00');
    view.unmount();
    expect(vi.getTimerCount()).toBeLessThanOrEqual(1);
  });

  it('tints from the background image and resets the tint when the colour cannot be read', () => {
    const error = vi.spyOn(console, 'error').mockImplementation(() => {});
    const { container } = render(h(CallsignSlide, props));
    const overlay = container.querySelector('.mix-blend-multiply') as HTMLElement;
    const image = container.querySelector('img') as HTMLImageElement;
    expect(image.getAttribute('src')).toBe('./modoitaliano/images/nyc.jpg');

    getColor.mockReturnValueOnce({ hex: '#00ff00' });
    fireEvent.load(image);
    expect(overlay.style.background).toContain('#00ff00');

    getColor.mockImplementationOnce(() => {
      throw new Error('tainted canvas');
    });
    fireEvent.load(image);
    expect(error).toHaveBeenCalledOnce();
    expect(overlay.style.background).toContain('#b21100');
  });
});

describe('LiveEventSlide', () => {
  const update = (n: number, extra: Record<string, unknown> = {}) => ({ time: `10:0${n}`, text: `Update ${n}`, ...extra });
  const event = (updates: LiveEventData['updates'], extra: Partial<LiveEventData> = {}): LiveEventData => ({
    category: 'POLITICA',
    title: 'Live title',
    excerpt: 'Live excerpt',
    image: 'https://img.test/live.jpg',
    alt: 'alt',
    url: 'https://modoitaliano.fm/story',
    liveUrl: 'https://modoitaliano.fm/live',
    updatedAt: '2026-03-11T00:00:00.000Z',
    updates,
    ...extra,
  });
  const renderSlide = (data: LiveEventData, language: 'en' | 'es' | 'it' = 'en') => render(h(LiveEventSlide, { event: data, progress: 0, language }));

  it('shows the event header, excerpt and its update timeline', () => {
    renderSlide(event([update(1), update(2)]));
    expect(screen.getByText('EN VIVO')).toBeTruthy();
    expect(screen.getByText('POLITICA')).toBeTruthy();
    expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Live title');
    expect(screen.getByText('Live excerpt')).toBeTruthy();
    expect(screen.getByRole('heading', { level: 2 }).textContent).toBe('ACTUALIZACIONES EN VIVO');
    expect(screen.getByText('Update 1')).toBeTruthy();
    expect(screen.getByText('Update 2')).toBeTruthy();
    expect(screen.getByText('10:01')).toBeTruthy();
  });

  it('omits the excerpt when absent and says so when there are no updates', () => {
    renderSlide(event([], { excerpt: undefined }));
    expect(screen.queryByText('Live excerpt')).toBeNull();
    expect(screen.getByText('No updates yet')).toBeTruthy();
    cleanup();
    renderSlide(event([]), 'it');
    expect(screen.getByText('Nessun aggiornamento')).toBeTruthy();
  });

  it('formats update times from a timestamp, falls back to the label, and hides the time when neither exists', () => {
    renderSlide(event([update(1, { timestamp: '2026-03-11T09:05:00Z' }), { text: 'No time at all' }]));
    // timestamp wins over the label, 24 hour clock
    expect(screen.getByText('09:05')).toBeTruthy();
    expect(screen.queryByText('10:01')).toBeNull();
    expect(screen.getByText('No time at all').parentElement!.querySelectorAll('span')).toHaveLength(0);
  });

  it('renders html updates as plain text and skips updates with no body', () => {
    renderSlide(event([{ time: '11:00', html: '<p>Hello <a href="/x">linked</a> <img src="x.png"/>world</p>' }, { time: '11:01' }]));
    expect(screen.getByText('Hello linked world')).toBeTruthy();
    expect(document.querySelector('a')).toBeNull();
    // the body-less update still shows its time
    expect(screen.getByText('11:01')).toBeTruthy();
  });

  it('scrolls through the updates four at a time when there are more than four', () => {
    const updates = [1, 2, 3, 4, 5, 6].map((n) => update(n));
    renderSlide(event(updates));
    const texts = () => Array.from(document.querySelectorAll('p')).map((p) => p.textContent).filter((text) => text?.startsWith('Update'));
    expect(texts()).toEqual(['Update 1', 'Update 2', 'Update 3', 'Update 4']);
    act(() => {
      vi.advanceTimersByTime(5000);
    });
    expect(texts()).toEqual(['Update 2', 'Update 3', 'Update 4', 'Update 5']);
    act(() => {
      vi.advanceTimersByTime(10_000);
    });
    expect(texts()).toEqual(['Update 4', 'Update 5', 'Update 6', 'Update 1']);
  });

  it('does not cycle with four or fewer updates and clears the cycle timer on unmount', () => {
    const view = renderSlide(event([1, 2, 3, 4].map((n) => update(n))));
    expect(vi.getTimerCount()).toBe(0);
    act(() => {
      vi.advanceTimersByTime(20_000);
    });
    expect(screen.getByText('Update 1')).toBeTruthy();
    view.unmount();
    cleanup();
    const long = renderSlide(event([1, 2, 3, 4, 5].map((n) => update(n))));
    expect(vi.getTimerCount()).toBe(1);
    long.unmount();
    expect(vi.getTimerCount()).toBe(0);
  });

  it('encodes the live url in the QR code, or the story url when there is no live url', () => {
    const withLive = renderSlide(event([]));
    const liveQr = (screen.getByAltText('QR code') as HTMLImageElement).getAttribute('src');
    expect(decodeQr(liveQr!)).toContain('<svg');
    withLive.unmount();
    renderSlide(event([], { liveUrl: undefined }));
    const storyQr = (screen.getByAltText('QR code') as HTMLImageElement).getAttribute('src');
    expect(storyQr).not.toBe(liveQr);
    cleanup();
    renderSlide(event([], { liveUrl: undefined, url: 'https://modoitaliano.fm/live' }));
    expect((screen.getByAltText('QR code') as HTMLImageElement).getAttribute('src')).toBe(liveQr);
  });

  it('tints from the event image and keeps the default tint when the colour cannot be read', () => {
    const { container } = renderSlide(event([]));
    const overlay = container.querySelector('.mix-blend-multiply') as HTMLElement;
    const image = container.querySelector('img') as HTMLImageElement;
    expect(image.getAttribute('src')).toBe('https://img.test/live.jpg');
    getColor.mockReturnValueOnce({ hex: '#0000ff' });
    fireEvent.load(image);
    expect(overlay.style.background).toContain('#0000ff');
    getColor.mockImplementationOnce(() => {
      throw new Error('tainted canvas');
    });
    fireEvent.load(image);
    expect(overlay.style.background).toContain('#b21100');
  });
});

// @vitest-environment happy-dom
import { act, cleanup, renderHook } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { useSSE } from './useSSE.js';

const encoder = new TextEncoder();

function openStream() {
  let controller!: ReadableStreamDefaultController<Uint8Array>;
  const body = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c;
    },
  });
  return {
    body,
    push: (text: string) => controller.enqueue(encoder.encode(text)),
    close: () => controller.close(),
  };
}

const okResponse = (body: ReadableStream<Uint8Array> | null) => ({ ok: true, status: 200, body });

const settle = async (ms = 0) => {
  await act(async () => {
    await vi.advanceTimersByTimeAsync(ms);
  });
};

let log: ReturnType<typeof vi.spyOn>;
let errorLog: ReturnType<typeof vi.spyOn>;

beforeEach(() => {
  vi.useFakeTimers();
  log = vi.spyOn(console, 'log').mockImplementation(() => {});
  errorLog = vi.spyOn(console, 'error').mockImplementation(() => {});
});
afterEach(() => {
  cleanup();
  vi.useRealTimers();
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe('useSSE', () => {
  it('stays idle without opening a connection when disabled', async () => {
    const fetchStub = vi.fn();
    vi.stubGlobal('fetch', fetchStub);
    const { result } = renderHook(() => useSSE({ url: '/stream', enabled: false }));
    await settle(10_000);
    expect(fetchStub).not.toHaveBeenCalled();
    expect(result.current).toEqual({ isConnected: false, error: null });
  });

  it('connects without caching, reports the connection and delivers parsed messages', async () => {
    const stream = openStream();
    const fetchStub = vi.fn().mockResolvedValue(okResponse(stream.body));
    vi.stubGlobal('fetch', fetchStub);
    const onMessage = vi.fn();
    const { result } = renderHook(() => useSSE({ url: '/stream', onMessage }));
    await settle();

    expect(fetchStub).toHaveBeenCalledOnce();
    const [url, init] = fetchStub.mock.calls[0];
    expect(url).toBe('/stream');
    expect(init.cache).toBe('no-store');
    expect(init.signal).toBeInstanceOf(AbortSignal);
    expect(result.current).toEqual({ isConnected: true, error: null });

    stream.push('data: {"type":"one","n":1}\n');
    await settle();
    expect(onMessage).toHaveBeenCalledWith({ type: 'one', n: 1 });
  });

  it('reassembles messages split across chunks and ignores noise', async () => {
    const stream = openStream();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse(stream.body)));
    const onMessage = vi.fn();
    renderHook(() => useSSE({ url: '/stream', onMessage }));
    await settle();

    stream.push('data: {"type":"sp');
    await settle();
    expect(onMessage).not.toHaveBeenCalled();
    stream.push('lit"}\n\n: comment\nevent: ping\ndata: [DONE]\ndata: not json\n  \ndata: {"type":"two"}\ndata: {"type":"tail"}');
    await settle();
    // the unterminated last line stays buffered until its newline arrives
    expect(onMessage.mock.calls.map(([m]) => m.type)).toEqual(['split', 'two']);
    stream.push('\n');
    await settle();
    expect(onMessage.mock.calls.map(([m]) => m.type)).toEqual(['split', 'two', 'tail']);
  });

  it('delivers to the latest callback without reconnecting', async () => {
    const stream = openStream();
    const fetchStub = vi.fn().mockResolvedValue(okResponse(stream.body));
    vi.stubGlobal('fetch', fetchStub);
    const first = vi.fn();
    const second = vi.fn();
    const { rerender } = renderHook(({ cb }) => useSSE({ url: '/stream', onMessage: cb }), { initialProps: { cb: first } });
    await settle();
    rerender({ cb: second });
    stream.push('data: {"type":"x"}\n');
    await settle();
    expect(first).not.toHaveBeenCalled();
    expect(second).toHaveBeenCalledOnce();
    expect(fetchStub).toHaveBeenCalledOnce();
  });

  it('tolerates messages when no callback is given', async () => {
    const stream = openStream();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse(stream.body)));
    const { result } = renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    stream.push('data: {"type":"x"}\n');
    await settle();
    expect(result.current.isConnected).toBe(true);
    expect(result.current.error).toBeNull();
  });

  it('reports an HTTP failure and retries after the reconnect interval', async () => {
    const stream = openStream();
    const fetchStub = vi
      .fn()
      .mockResolvedValueOnce({ ok: false, status: 503, body: null })
      .mockResolvedValueOnce(okResponse(stream.body));
    vi.stubGlobal('fetch', fetchStub);
    const { result } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 1000 }));
    await settle();

    expect(result.current.isConnected).toBe(false);
    expect(result.current.error?.message).toBe('SSE fetch failed: 503');
    expect(errorLog).toHaveBeenCalled();

    await settle(999);
    expect(fetchStub).toHaveBeenCalledTimes(1);
    await settle(1);
    expect(fetchStub).toHaveBeenCalledTimes(2);
    expect(result.current).toEqual({ isConnected: true, error: null });
  });

  it('uses a three second reconnect interval by default', async () => {
    const fetchStub = vi.fn().mockRejectedValue(new Error('offline'));
    vi.stubGlobal('fetch', fetchStub);
    renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    await settle(2999);
    expect(fetchStub).toHaveBeenCalledTimes(1);
    await settle(1);
    expect(fetchStub).toHaveBeenCalledTimes(2);
  });

  it('reports a response without a body', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse(null)));
    const { result } = renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    expect(result.current.error?.message).toBe('SSE response has no body');
  });

  it('wraps non-Error failures', async () => {
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue({ name: 'Weird', toString: () => 'odd failure' }));
    const { result } = renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.error?.message).toBe('odd failure');
  });

  it('reconnects after the stream ends and clears a previous error', async () => {
    const first = openStream();
    const second = openStream();
    const fetchStub = vi
      .fn()
      .mockRejectedValueOnce(new Error('first attempt failed'))
      .mockResolvedValueOnce(okResponse(first.body))
      .mockResolvedValueOnce(okResponse(second.body));
    vi.stubGlobal('fetch', fetchStub);
    const { result } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 500 }));
    await settle();
    expect(result.current.error?.message).toBe('first attempt failed');
    await settle(500);
    expect(result.current).toEqual({ isConnected: true, error: null });

    first.close();
    await settle();
    expect(fetchStub).toHaveBeenCalledTimes(2);
    await settle(500);
    expect(fetchStub).toHaveBeenCalledTimes(3);
  });

  it('treats an aborted request as quiet and still schedules a reconnect', async () => {
    const abort = Object.assign(new Error('aborted'), { name: 'AbortError' });
    const fetchStub = vi.fn().mockRejectedValue(abort);
    vi.stubGlobal('fetch', fetchStub);
    const { result } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 100 }));
    await settle();
    expect(result.current.error).toBeNull();
    expect(errorLog).not.toHaveBeenCalled();
    await settle(100);
    expect(fetchStub).toHaveBeenCalledTimes(2);
  });

  it('closes the stream, aborts the request and stops reconnecting on unmount', async () => {
    const stream = openStream();
    let signal!: AbortSignal;
    const fetchStub = vi.fn().mockImplementation(async (_url: string, init: RequestInit) => {
      signal = init.signal as AbortSignal;
      return okResponse(stream.body);
    });
    vi.stubGlobal('fetch', fetchStub);
    const { unmount } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 100 }));
    await settle();
    expect(signal.aborted).toBe(false);
    unmount();
    expect(signal.aborted).toBe(true);
    await settle(1000);
    expect(fetchStub).toHaveBeenCalledOnce();
    expect(vi.getTimerCount()).toBe(0);
  });

  it('cancels a pending reconnect on unmount', async () => {
    const fetchStub = vi.fn().mockRejectedValue(new Error('offline'));
    vi.stubGlobal('fetch', fetchStub);
    const { unmount } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 5000 }));
    await settle();
    expect(vi.getTimerCount()).toBe(1);
    unmount();
    expect(vi.getTimerCount()).toBe(0);
    await settle(10_000);
    expect(fetchStub).toHaveBeenCalledOnce();
  });

  it('ignores a failure that lands after unmount', async () => {
    let rejectFetch!: (error: Error) => void;
    const fetchStub = vi.fn().mockReturnValue(new Promise((_, reject) => (rejectFetch = reject)));
    vi.stubGlobal('fetch', fetchStub);
    const { result, unmount } = renderHook(() => useSSE({ url: '/stream', reconnectInterval: 100 }));
    await settle();
    unmount();
    rejectFetch(new Error('late'));
    await settle(1000);
    expect(result.current.error).toBeNull();
    expect(errorLog).not.toHaveBeenCalled();
    expect(fetchStub).toHaveBeenCalledOnce();
  });

  it('survives a reader that throws while being cancelled', async () => {
    const reader = {
      read: vi.fn().mockReturnValue(new Promise(() => {})),
      cancel: vi.fn(() => {
        throw new Error('cannot cancel');
      }),
    };
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse({ getReader: () => reader } as unknown as ReadableStream<Uint8Array>)));
    const { unmount } = renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    expect(() => unmount()).not.toThrow();
    expect(reader.cancel).toHaveBeenCalledOnce();
  });

  it('drops the connection state when disabled after connecting', async () => {
    const stream = openStream();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse(stream.body)));
    const { result, rerender } = renderHook(({ enabled }) => useSSE({ url: '/stream', enabled }), { initialProps: { enabled: true } });
    await settle();
    expect(result.current.isConnected).toBe(true);
    rerender({ enabled: false });
    await settle();
    expect(result.current).toEqual({ isConnected: false, error: null });
  });

  it('logs the connection and each message type', async () => {
    const stream = openStream();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(okResponse(stream.body)));
    renderHook(() => useSSE({ url: '/stream' }));
    await settle();
    stream.push('data: {"type":"hello"}\n');
    await settle();
    expect(log).toHaveBeenCalledWith('[SSE] connected to', '/stream');
    expect(log).toHaveBeenCalledWith('[SSE] message:', 'hello');
  });
});

